 {!selected&&['Cases','My cases'].includes(section)&&<div className="work-fields"><label className="work-field"><span>Service filter</span><select value={caseFilters.service||''} onChange={e=>setCaseFilters({...caseFilters,service:e.target.value})}><option value="">All services</option>{serviceDefaults.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label className="work-field"><span>Status filter</span><input value={caseFilters.status||''} onChange={e=>setCaseFilters({...caseFilters,status:e.target.value})} placeholder="Exact workflow status"/></label><label className="work-field"><span>Destination filter</span><input value={caseFilters.destination||''} onChange={e=>setCaseFilters({...caseFilters,destination:e.target.value})} placeholder="Exact destination"/></label>{staffMode&&<label className="work-field"><span>Assigned employee</span><select value={caseFilters.assignee||''} onChange={e=>setCaseFilters({...caseFilters,assignee:e.target.value})}><option value="">All permitted assignments</option>{directory.map(p=><option value={p.id} key={p.id}>{p.email}</option>)}</select></label>}<label className="work-check"><input type="checkbox" checked={caseFilters.due==='overdue'} onChange={e=>setCaseFilters({...caseFilters,due:e.target.checked?'overdue':''})}/>Overdue cases only</label></div>}
 {!data&&!error&&<p role="status" className="work-empty">Loading your records…</p>}
 {data&&['Cases','My cases'].includes(section)&&(board?<div className="case-board">{[...new Set(data.cases.map((c:any)=>c.status))].map((status:any)=><section key={status}><h3>{status}</h3>{data.cases.filter((c:any)=>c.status===status).map((c:any)=><button key={c.id} onClick={()=>setSelected(c.id)}><strong>{c.reference}</strong><span>{c.name}</span><small>{c.destination}</small></button>)}</section>)}</div>:<Rows rows={data.cases} onOpen={(r:any)=>setSelected(r.id)}/>)}
 {data?.next&&<button className="work-button secondary" onClick={async()=>{const next=await api('cases?offset='+data.next+'&search='+encodeURIComponent(search)+filterQuery);setData({cases:[...data.cases,...next.cases],next:next.next})}}>Load more cases</button>}
 {data&&section==='Overview'&&<><div className="work-metrics"><article><span>Cases in your scope</span><strong>{data.counts.reduce((n:number,x:any)=>n+x.total,0)}</strong></article><article><span>Open tasks assigned to you</span><strong>{data.totals.tasks}</strong></article><article><span>Overdue tasks</span><strong>{data.totals.overdue}</strong></article><article><span>Upcoming appointments</span><strong>{data.totals.appointments}</strong></article></div><h2>Case workload</h2><Rows rows={data.counts}/><h2>Document review queue</h2><Rows rows={data.review} onOpen={(r:any)=>setSelected(r.case_id)}/></>}
 {data&&section==='Documents'&&<Rows rows={data.review} onOpen={(r:any)=>setSelected(r.case_id)}/>}
 {data&&section==='Tasks & calendar'&&<><h2>My tasks</h2><Rows rows={data.tasks} onOpen={(r:any)=>setSelected(r.case_id)}/><h2>Appointments · Europe/London</h2><Rows rows={data.appointments} onOpen={(r:any)=>setSelected(r.case_id)}/></>}
 {data&&section==='Clients'&&<><Rows rows={data} onOpen={(r:any)=>{setNewCase(r.id)}}/><Form title="New client — telephone, walk-in, WhatsApp or email" onSave={async(d:any)=>{const created=await api('admin/clients',d);setNewCase(created.id);load()}}><Field name="name"/><Field name="email" type="email"/><Field name="phone" required={false}/><Field name="language" options={['en','bn']}/></Form></>}
 {data&&section==='Staff & access'&&<StaffSettings data={data} reload={load}/>}
