 {data&&section==='Authorisation'&&<><Rows rows={data}/><Form title="Record verified professional authorisation" hint="Check the official register, responsible professional and permitted scope. This record does not itself constitute regulatory approval." onSave={async(d:any)=>{await api('admin/authorisations',{...d,expiresAt:Date.parse(d.expiresAt),verified:d.verified==='on'});load()}}><Field name="service" options={['uk-visit','uk-applications']}/><Field name="professional"/><Field name="registration"/><Field name="registerUrl" type="url"/><Field name="scope" type="textarea"/><Field name="expiresAt" type="date"/><label className="work-check"><input type="checkbox" name="verified" required/>I checked authorisation and permitted scope.</label></Form></>}
 {data&&section==='Settings'&&<><p>Staff password login, outbound email, automated WhatsApp, live airline booking, payments and OCR are not connected. Manual workflows remain available.</p><Rows rows={data.settings}/><Form title="Retention policy" hint="Records are flagged for reviewed deletion; no automatic destructive purge is enabled." onSave={async(d:any)=>{await api('admin/settings',{id:'retention',revision:data.settings.find((s:any)=>s.id==='retention')?.revision||0,value:{days:Number(d.days)}});load()}}><Field name="days" type="number" defaultValue="365"/></Form><h2>Privacy requests</h2><Rows rows={data.privacyRequests}/><Form title="Update a privacy request" onSave={async(d:any)=>{await api('admin/privacy-review',d);load()}}><Field name="requestId" options={data.privacyRequests.map((r:any)=>({value:r.id,label:r.kind+' · '+r.account_id}))}/><Field name="status" options={['under review','completed','declined with explanation']}/><Field name="reason" type="textarea"/></Form><button className="work-button secondary" onClick={async()=>{try{const r=await api('admin/backup',{});const url=URL.createObjectURL(new Blob([JSON.stringify(r)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='trip-bhai-encrypted-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){setError((e as Error).message)}}}>Download encrypted backup</button><p className="muted">Requires the separately configured backup key. Keep that key outside the backup. Session cookies are excluded; restore is restricted to a fresh database.</p></>}
